#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class RunRiskBindingTests {
  internal static JObject Packet(string name="signed-original-entry")=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-risk-run-binding-traces-20261003.json"))["traces"].Single(r=>(string)r["name"]==name)["body"].DeepClone();
  internal static JObject Trust(JObject p)=>new JObject{["accountId"]=p["frozen"]["accountId"],["runId"]=p["frozen"]["runId"],["startSnapshotHash"]=p["frozen"]["startSnapshotHash"],["progressRevision"]=p["progress"]["revision"],["packetHash"]=p["packetHash"]};
  internal static Type Type(string name){var t=typeof(RunApiHttpResponse).Assembly.GetType("LastRail.Run."+name);Assert.NotNull(t,"Missing original metadata boundary "+name);return t;}
  internal static object Call(object owner,string name,params object[] args){var t=owner as Type??owner.GetType();var m=t.GetMethod(name);Assert.NotNull(m,"Missing metadata method "+name);try{return m.Invoke(owner is Type?null:owner,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  static object Read(JObject p,JObject trust=null)=>Call(Type("RunRiskBindingSnapshot"),"Read",p,trust??Trust(p));
  internal static GameApiAuthSessionSnapshot Session(string account="a")=>new GameApiAuthSessionSnapshot(account,"ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
  internal static RunApiHttpResponse Response(JObject p,int status=200){var method=typeof(RunApiHttpResponse).GetMethods().SingleOrDefault(m=>m.Name=="Success"&&m.GetParameters().Length==3);Assert.NotNull(method,"Missing response header preservation");return (RunApiHttpResponse)method.Invoke(null,new object[]{status,p.ToString(),new[]{new RunApiHttpHeader("Cache-Control","no-store"),new RunApiHttpHeader("X-Combat-B-Risk-Binding-Version","combat.b-risk-run-binding.v1.20261003"),new RunApiHttpHeader("ETag",(string)p["packetHash"]??"")}});}
  internal sealed class Wire:IRunApiHttpTransport {public RunApiHttpRequest Last;public int Count;public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply;public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest request){Last=request;Count++;return Reply(request);}}
  static object Client(Wire wire,Func<GameApiAuthSessionSnapshot> session,Func<long> generation)=>Activator.CreateInstance(Type("RunRiskBindingClient"),new object[]{new GameApiAuthenticatedHttpTransport(wire),session,generation});
  static Task Refresh(object c,JObject trust,string match=null)=> (Task)Call(c,"RefreshAsync",trust,match,default(System.Threading.CancellationToken));
  static object Snapshot(object c)=>c.GetType().GetProperty("Snapshot").GetValue(c);
  [Test] public void OriginalEntryAndVisitedFiveRemainMetadataOnly(){foreach(var name in new[]{"signed-original-entry","actual-original-visited-depth-five","original-terminal-read-not-combat-authority"}){var p=Packet(name);var s=Read(p);var capture=(JObject)Call(s,"Capture");Assert.IsTrue(JToken.DeepEquals(p,capture));Assert.Throws<InvalidOperationException>(()=>Call(s,"RequireScalingSource"));p["frozen"]["selectedRisk"]="I";Assert.AreEqual("V",(string)((JObject)Call(s,"Capture"))["frozen"]["selectedRisk"]);}}
  [TestCase("accountId")][TestCase("runId")][TestCase("startSnapshotHash")][TestCase("progressRevision")][TestCase("packetHash")]
  public void IndependentTrustRejectsCrossOwnerStaleOrSelfHash(string field){var p=Packet();var t=Trust(p);t[field]=field=="progressRevision"?new JValue(2):new JValue(field.EndsWith("Hash")?new string('f',64):"other");Assert.Throws<ArgumentException>(()=>Read(p,t));}
  [Test] public void FullStrictPacketRejectsRehashUnauthorizedSupportAndExtraFields(){foreach(var change in new Action<JObject>[]{p=>p["support"]["scaling"]=true,p=>p["originalProfile"]["rawHp"]=700,p=>p["version"]="old",p=>p["frozen"]["originalCombatContextId"]=p["frozen"]["runId"].DeepClone(),p=>p["frozen"]["riskApplicationVersion"]="combat.b-operation-risk.v1.20261003",p=>p["originalProfile"]["profile"]="ORDINARY_15_WAVE"}){var p=Packet();change(p);Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}var missing=Packet();foreach(var key in new[]{"contentVersion"})missing["frozen"][key]=JValue.CreateNull();foreach(var key in new[]{"publicationVersion","publicationHash","currentEncounterRef","currentEncounterVersion","currentEncounterDefinitionHash"})missing["originalProfile"][key]=JValue.CreateNull();Rehash(missing);Assert.DoesNotThrow(()=>Read(missing));}
  [Test] public async Task ExistingBearerChainAndStrictModelPublishExactReadOnlyPacket(){var p=Packet();var wire=new Wire{Reply=r=>Task.FromResult(Response(p))};var owner=Session();var c=Client(wire,()=>owner,()=>1);await Refresh(c,Trust(p));Assert.NotNull(Snapshot(c));Assert.AreEqual("GET",wire.Last.Method);Assert.IsNull(wire.Last.BodyJson);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"&&h.Value=="Bearer lst1.fixture"));Assert.IsFalse(wire.Last.Headers.Any(h=>h.Name.Contains("Account")));Assert.IsFalse((bool)Call(Snapshot(c),"ScalingSupported"));}
  [Test] public async Task OwnerGenerationChangeDiscardsLateResponse(){var p=Packet();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>pending.Task};var owner=Session();long generation=1;var c=Client(wire,()=>owner,()=>generation);var task=Refresh(c,Trust(p));generation++;pending.SetResult(Response(p));await task;Assert.IsNull(Snapshot(c));}
  [Test] public void ExistingAccountModelComposesIndependentMetadataOwner(){var p=Packet();var wire=new Wire{Reply=r=>Task.FromResult(Response(p))};var session=Session();using var model=new AccountScreenRuntime(wire,null,()=>session,()=>1);var property=model.GetType().GetProperty("RiskRunBinding");Assert.NotNull(property,"Existing Model must compose the source consumer");var c=property.GetValue(model);Assert.AreSame(c,property.GetValue(model));}
  internal static JObject Rehash(JObject p){p.Remove("packetHash");p["packetHash"]=LastRail.Battle.BDirectAttackInput.Digest(p).Substring(7);return p;}
  [TestCase(0,null,"NO_VISITED_NODE")][TestCase(1,"EARLY","VISITED_NODE")][TestCase(4,"EARLY","VISITED_NODE")][TestCase(5,"MIDDLE","VISITED_NODE")][TestCase(8,"MIDDLE","VISITED_NODE")][TestCase(9,"LATE","VISITED_NODE")][TestCase(11,"LATE","VISITED_NODE")][TestCase(12,null,"BOSS_SEPARATE_PROFILE")]
  public void VisitedDepthClassifiesPositionWithoutScaling(int depth,string band,string status){var p=Packet();p["progress"]["visitDepth"]=depth;p["progress"]["band"]=band==null?JValue.CreateNull():new JValue(band);p["progress"]["bandStatus"]=status;p["progress"]["pendingEdgeId"]="pending-next-edge";Rehash(p);var s=Read(p);Assert.IsTrue(JToken.DeepEquals(p,Call(s,"Capture") as JObject));Assert.Throws<InvalidOperationException>(()=>Call(s,"RequireScalingSource"));p["progress"]["band"]="LATE";if(band!="LATE"){Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}}
  [Test] public async Task StaleAndAuthClearProjectionWithoutRetry(){var p=Packet();var owner=Session();var wire=new Wire{Reply=r=>Task.FromResult(Response(p))};var c=Client(wire,()=>owner,()=>1);await Refresh(c,Trust(p));Assert.NotNull(Snapshot(c));wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_risk_run_stale\"}"));await Refresh(c,Trust(p),(string)p["packetHash"]);Assert.IsNull(Snapshot(c));Assert.AreEqual("STALE",c.GetType().GetProperty("Status").GetValue(c));Assert.AreEqual(2,wire.Count);wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(401,"{\"errorCode\":\"auth_session_invalid\"}"));await Refresh(c,Trust(p));Assert.IsNull(Snapshot(c));Assert.AreEqual("AUTH_REQUIRED",c.GetType().GetProperty("Status").GetValue(c));}
  [Test] public async Task CancellationAndDisposeCannotPublishLateOrNotifyAfterUnbind(){var p=Packet();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>pending.Task};var owner=Session();var c=Client(wire,()=>owner,()=>1);using var stop=new System.Threading.CancellationTokenSource();var task=(Task)Call(c,"RefreshAsync",Trust(p),null,stop.Token);stop.Cancel();await task;Assert.AreEqual("CANCELLED",c.GetType().GetProperty("Status").GetValue(c));((IDisposable)c).Dispose();pending.SetResult(Response(p));await Task.Yield();Assert.IsNull(Snapshot(c));Assert.Throws<ObjectDisposedException>(()=>Call(c,"RestoreVerified",p,Trust(p)));}
  [Test] public async Task FrozenOriginalConflictAndUnsupportedRestoreDoNotReplaceModel(){var p=Packet();var owner=Session();var wire=new Wire{Reply=r=>Task.FromResult(Response(p))};var c=Client(wire,()=>owner,()=>1);await Refresh(c,Trust(p));var changed=(JObject)p.DeepClone();changed["frozen"]["selectedRisk"]="I";Rehash(changed);wire.Reply=r=>Task.FromResult(Response(changed));await Refresh(c,Trust(changed));Assert.IsNull(Snapshot(c));Assert.AreEqual("CONTRACT_MISMATCH",c.GetType().GetProperty("Status").GetValue(c));Call(c,"RestoreVerified",p,Trust(p));Assert.NotNull(Snapshot(c));var bad=Trust(p);bad["progressRevision"]=2;Assert.Throws<ArgumentException>(()=>Call(c,"RestoreVerified",p,bad));Assert.IsTrue(JToken.DeepEquals(p,(JObject)Call(Snapshot(c),"Capture")));}
  [Test] public async Task MissingNoStoreOrEtagCannotPublishTrustedBody(){var p=Packet();var owner=Session();var wire=new Wire{Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,p.ToString()))};var c=Client(wire,()=>owner,()=>1);await Refresh(c,Trust(p));Assert.IsNull(Snapshot(c));Assert.AreEqual("CONTRACT_MISMATCH",c.GetType().GetProperty("Status").GetValue(c));}
  [Test] public void NativeHttpAdapterHasOwnedRequestDisposal(){Assert.IsTrue(typeof(IDisposable).IsAssignableFrom(typeof(UnityWebRequestRunApiHttpAdapter)),"Native HTTP owner must cancel and release its own requests");}
  [Test] public async Task DisposingConsumerCancelsItsOwnAwaitWithoutDisposingBorrowedWire(){var p=Packet();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>pending.Task};var owner=Session();var c=Client(wire,()=>owner,()=>1);var task=Refresh(c,Trust(p));((IDisposable)c).Dispose();try{var finished=await Task.WhenAny(task,Task.Delay(200));Assert.AreSame(task,finished,"Disposed consumer left its owned await running");Assert.IsNull(Snapshot(c));}finally{pending.TrySetResult(Response(p));await task;}}
  [Test] public async Task VerifiedNewerRestoreSupersedesOlderPendingResponseAndError(){foreach(bool error in new[]{false,true}){var old=Packet();var newer=Packet("actual-original-visited-depth-five");var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>pending.Task};var owner=Session();var c=Client(wire,()=>owner,()=>1);var task=Refresh(c,Trust(old));Call(c,"RestoreVerified",newer,Trust(newer));pending.SetResult(error?RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_risk_run_stale\"}"):Response(old));await task;Assert.IsTrue(JToken.DeepEquals(newer,(JObject)Call(Snapshot(c),"Capture")));Assert.AreEqual("READY",c.GetType().GetProperty("Status").GetValue(c));((IDisposable)c).Dispose();}}
  [Test] public async Task FailingObserverDoesNotLeaveDisposedRequestScopeAttached(){var p=Packet();var owner=Session();var wire=new Wire{Reply=r=>Task.FromResult(Response(p))};var c=(RunRiskBindingClient)Client(wire,()=>owner,()=>1);Action broken=()=>throw new InvalidOperationException("observer failure");c.Changed+=broken;Assert.ThrowsAsync<InvalidOperationException>(async()=>await c.RefreshAsync(Trust(p)));c.Changed-=broken;Assert.DoesNotThrow(()=>c.Invalidate());await c.RefreshAsync(Trust(p));Assert.NotNull(c.Snapshot);c.Dispose();}
 }
}
#endif
